<script setup lang="ts">
import {computed,onScopeDispose,ref,watch} from 'vue'
import {can,projectId} from '@/core/session'
import {onIdentityChange} from '@/core/http'
import {automationTimezone,type AutomationMixedConfig} from './automation-mixed-triggers'
const props=defineProps<{value:AutomationMixedConfig;projectTimezone?:string|null;disabled?:boolean}>(),emit=defineEmits<{change:[mode:'FOLLOW_PROJECT'|'CUSTOM',timezone?:string]}>()
const open=ref(false),zone=ref(''),error=ref(''),blocked=computed(()=>props.disabled||!projectId.value||!can('rule:manage'))
const customZone=ref(props.value.timezoneMode==='CUSTOM'?props.value.timezone:Intl.DateTimeFormat().resolvedOptions().timeZone)
watch(()=>props.value,value=>{if(value.timezoneMode==='CUSTOM')customZone.value=value.timezone})
const zones=computed(()=>{const priority=['Asia/Shanghai','Asia/Hong_Kong','Asia/Tokyo','Asia/Seoul','Asia/Singapore','Europe/London','Europe/Paris','Europe/Berlin','Europe/Moscow','America/New_York','America/Chicago','America/Denver','America/Los_Angeles','America/Toronto','Australia/Sydney','UTC'];return [...new Set([...priority,customZone.value,props.projectTimezone,...(Intl.supportedValuesOf?Intl.supportedValuesOf('timeZone'):[])].filter((v):v is string=>!!v))]})
function offset(value:string){try{return new Intl.DateTimeFormat('en-US',{timeZone:value,timeZoneName:'longOffset'}).formatToParts(new Date()).find(part=>part.type==='timeZoneName')?.value.replace('GMT','UTC')??''}catch{return ''}}
function display(value:string|undefined|null){return value?`${value.replace(/_/g,' ')} ${offset(value)}`:'—'}
function changeMode(mode:unknown){if(mode==='CUSTOM')selectCustom();else if(mode==='FOLLOW_PROJECT'&&!blocked.value)emit('change','FOLLOW_PROJECT')}
function selectCustom(){if(!blocked.value&&props.value.timezoneMode!=='CUSTOM')emit('change','CUSTOM',customZone.value)}
function edit(){if(blocked.value)return;zone.value=props.value.timezoneMode==='CUSTOM'?props.value.timezone:props.projectTimezone&&automationTimezone(props.projectTimezone)?props.projectTimezone:customZone.value;error.value='';open.value=true}
function confirm(){if(blocked.value)return;if(!automationTimezone(zone.value)){error.value='请选择时区';return}customZone.value=zone.value;emit('change','CUSTOM',zone.value);open.value=false}
watch([projectId,()=>props.disabled],()=>{open.value=false});const dispose=onIdentityChange(()=>{open.value=false});onScopeDispose(dispose)
</script>
<template><el-form-item label="时区设置"><div class="timezone-options-container"><el-radio-group :model-value="value.timezoneMode" class="timezone-radio-group" :disabled="blocked" @change="changeMode"><div class="timezone-option-box" :class="{'is-active':value.timezoneMode==='FOLLOW_PROJECT'}" @click="!blocked&&emit('change','FOLLOW_PROJECT')"><el-radio :model-value="value.timezoneMode" value="FOLLOW_PROJECT" aria-label="跟随项目时区" :disabled="blocked" @update:model-value="!blocked&&emit('change','FOLLOW_PROJECT')">跟随项目时区</el-radio><div class="timezone-hint">{{display(projectTimezone)}}</div></div><div class="timezone-option-box" :class="{'is-active':value.timezoneMode==='CUSTOM'}" @click="selectCustom"><el-radio :model-value="value.timezoneMode" value="CUSTOM" aria-label="自定义时区" :disabled="blocked" @update:model-value="selectCustom">自定义时区</el-radio><div class="timezone-hint timezone-hint-with-action"><span>{{display(value.timezoneMode==='CUSTOM'?value.timezone:customZone)}}</span><el-button text type="primary" size="small" aria-label="编辑触发时区" :disabled="blocked" @click.stop="edit">编辑</el-button></div></div></el-radio-group></div><div class="timezone-setting-tip">时区设置会影响定时类触发器的时间计算。</div></el-form-item><el-dialog v-if="open" :model-value="true" title="选择时区" width="500px" :lock-scroll="false" :close-on-click-modal="false" append-to-body @update:model-value="open=false"><el-select v-model="zone" filterable placeholder="选择时区" aria-label="触发器时区" :disabled="blocked" style="width:100%"><el-option v-for="item in zones" :key="item" :label="item.replace(/_/g,' ')" :value="item"><span style="float:left">{{item.replace(/_/g,' ')}}</span><span style="float:right;color:#8492a6;font-size:13px">{{offset(item)}}</span></el-option></el-select><el-alert v-if="error" :title="error" type="warning" :closable="false"/><template #footer><el-button :disabled="disabled" @click="open=false">取消</el-button><el-button type="primary" :disabled="blocked" @click="confirm">确定</el-button></template></el-dialog></template>
<style scoped>.timezone-options-container,.timezone-radio-group{display:flex;gap:10px;width:100%}.timezone-option-box{flex:1;border:1px solid #dcdfe6;border-radius:4px;padding:12px 16px;cursor:pointer;transition:background .2s}.timezone-option-box.is-active{border-color:#409eff;background:#ecf5ff}.timezone-hint{font-size:12px;color:#8492a6;margin-top:4px;line-height:1.4;padding-left:24px}.timezone-hint-with-action{display:flex;align-items:center;justify-content:space-between}.timezone-hint-with-action .el-button{padding:0;margin-left:8px;font-size:12px;line-height:1.4;height:auto;flex-shrink:0}.timezone-setting-tip{font-size:13px;color:#909399;margin-top:8px;line-height:1.4}</style>
